use crate::source::{FramePair,ProjectileRow};
pub const MAX_STEP:f64=60000.0;
#[derive(Clone,Copy)]struct Track{row:ProjectileRow,birth:u32,direction:[f64;2],internal:Option<crate::source::ProjectileInternal>}
#[derive(Clone,Copy,Debug)]pub struct Flight{pub kind:Option<u16>,pub motion:u8,pub category:u8,pub cooldown_event_tick:Option<u32>,pub handle:u64,pub caster:u32,pub team:i32,pub position:[f64;2],pub direction:[f64;2],pub age:f64,pub interpolated:bool}
pub struct Tracker{tick:Option<u32>,tracks:Vec<Track>,next:Vec<Track>,pub flights:Vec<Flight>}
fn delta(a:ProjectileRow,b:ProjectileRow)->[f64;2]{[b.1-a.1,b.2-a.2]}
pub fn continuous(a:ProjectileRow,b:ProjectileRow,ticks:u32)->bool{a.0==b.0&&a.3==b.3&&a.4==b.4&&a.5==0&&b.5==0&&(b.1-a.1).hypot(b.2-a.2)<=MAX_STEP*ticks as f64}
impl Tracker{
 pub fn new(capacity:usize)->Self{Self{tick:None,tracks:Vec::with_capacity(capacity),next:Vec::with_capacity(capacity),flights:Vec::with_capacity(capacity)}}
 pub fn sizes(&self)->[usize;6]{[self.tracks.len(),self.tracks.capacity(),self.next.len(),self.next.capacity(),self.flights.len(),self.flights.capacity()]}
 pub fn clear(&mut self){self.tick=None;self.tracks.clear();self.next.clear();self.flights.clear();}
 pub fn update(&mut self,pair:FramePair<'_>){let a=pair.a;if !a.pk.is_empty(){self.update_exact(pair);return;}if self.tick!=Some(a.tick){self.next.clear();let ticks=self.tick.map(|t|a.tick.saturating_sub(t)).unwrap_or(0);for row in &a.projectiles{if row.5!=0{continue;}let old=if (1..=4).contains(&ticks){self.tracks.iter().find(|t|continuous(t.row,*row,ticks))}else{None};let birth=old.map(|t|t.birth).unwrap_or(a.tick);let direction=old.map(|t|{let d=delta(t.row,*row);if d[0].hypot(d[1])>1.0{d}else{t.direction}}).unwrap_or([1.0,0.0]);self.next.push(Track{row:*row,birth,direction,internal:None});}std::mem::swap(&mut self.tracks,&mut self.next);self.tick=Some(a.tick);}
  self.flights.clear();for track in &self.tracks{let row=track.row;let next=pair.b.projectiles.iter().copied().find(|p|continuous(row,*p,1));let direction=next.map(|n|delta(row,n)).filter(|d|d[0].hypot(d[1])>1.0).unwrap_or(track.direction);let position=next.map(|n|[row.1+(n.1-row.1)*pair.alpha,row.2+(n.2-row.2)*pair.alpha]).unwrap_or([row.1,row.2]);let evidence=a.projectile_kinds.iter().find(|e|e.0==row.0&&e.1==row.3);self.flights.push(Flight{kind:None,motion:0,category:evidence.map(|e|e.2).unwrap_or(0),cooldown_event_tick:evidence.and_then(|e|e.3),handle:row.0,caster:row.3.saturating_add(1),team:row.4,position,direction,age:(a.tick.saturating_sub(track.birth)as f64+pair.alpha)/60.0,interpolated:next.is_some()});}
 }
 /// v5: 내부 ID+생성 틱으로 같은 투사체를 잇는다. 거리·시전자 추측과 쿨다운 추정을 쓰지 않는다.
 fn update_exact(&mut self,pair:FramePair<'_>){let a=pair.a;
  self.next.clear();for(row,p)in a.projectiles.iter().zip(&a.pk){if row.5!=0{continue;}let old=self.tracks.iter().find(|t|t.internal.is_some_and(|q|q.0==p.0&&q.2==p.2));
   let direction=old.map(|t|{let d=delta(t.row,*row);if self.tick.is_some_and(|t|t<a.tick)&&d[0].hypot(d[1])>1.0{d}else{t.direction}}).unwrap_or([1.0,0.0]);self.next.push(Track{row:*row,birth:p.2,direction,internal:Some(*p)});}
  std::mem::swap(&mut self.tracks,&mut self.next);self.tick=Some(a.tick);self.flights.clear();
  for track in &self.tracks{let row=track.row;let p=track.internal.unwrap();let next=pair.b.pk.iter().position(|q|q.0==p.0&&q.2==p.2).and_then(|i|pair.b.projectiles.get(i)).copied();
   let direction=next.map(|n|delta(row,n)).filter(|d|d[0].hypot(d[1])>1.0).unwrap_or(track.direction);let position=next.map(|n|[row.1+(n.1-row.1)*pair.alpha,row.2+(n.2-row.2)*pair.alpha]).unwrap_or([row.1,row.2]);
   self.flights.push(Flight{kind:Some(p.1),motion:p.3,category:0,cooldown_event_tick:None,handle:row.0,caster:row.3.saturating_add(1),team:row.4,position,direction,age:(a.tick.saturating_sub(track.birth)as f64+pair.alpha)/60.0,interpolated:next.is_some()});}
 }
}
#[cfg(test)]mod tests{use super::*;#[test]fn caster_handle_and_distance_guard(){let a=ProjectileRow(1,100.0,200.0,24,1,0);assert!(continuous(a,ProjectileRow(1,500.0,600.0,24,1,0),1));assert!(!continuous(a,ProjectileRow(1,500.0,600.0,25,1,0),1));assert!(!continuous(a,ProjectileRow(1,900000.0,600.0,24,1,0),1));assert!(!continuous(a,ProjectileRow(1,500.0,600.0,24,1,1),1));}
#[test]fn old_frame_defaults_and_handle_reuse(){let mut a:crate::source::Frame=serde_json::from_str(r#"{"tick":0,"kills":[0,0],"entities":[],"players":[]}"#).unwrap();assert!(a.projectiles.is_empty());let mut b:crate::source::Frame=serde_json::from_str(r#"{"tick":1,"kills":[0,0],"entities":[],"players":[]}"#).unwrap();a.projectiles=vec![ProjectileRow(1,100.0,200.0,24,1,0)];b.projectiles=vec![ProjectileRow(1,300.0,400.0,24,1,0)];let mut t=Tracker::new(4);t.update(FramePair{a:&a,b:&b,alpha:0.5});assert_eq!(t.flights[0].position,[200.0,300.0]);assert_eq!(t.flights[0].caster,25);assert!(t.flights[0].interpolated);b.projectiles[0].3=25;t.update(FramePair{a:&a,b:&b,alpha:0.5});assert_eq!(t.flights[0].position,[100.0,200.0]);assert!(!t.flights[0].interpolated);t.clear();assert!(t.flights.is_empty());}
#[test]fn exact_identity_survives_handle_reuse(){let mut a:crate::source::Frame=serde_json::from_str(r#"{"tick":10,"kills":[0,0],"entities":[],"players":[]}"#).unwrap();let mut b:crate::source::Frame=serde_json::from_str(r#"{"tick":11,"kills":[0,0],"entities":[],"players":[]}"#).unwrap();let p=crate::source::ProjectileInternal;a.projectiles=vec![ProjectileRow(1,0.0,0.0,24,1,0),ProjectileRow(2,1000.0,0.0,24,1,0)];a.pk=vec![p(7,0,9,6),p(8,1,9,2)];b.projectiles=vec![ProjectileRow(1,1200.0,0.0,24,1,0)];b.pk=vec![p(8,1,9,2)];let mut t=Tracker::new(4);t.update(FramePair{a:&a,b:&b,alpha:0.5});assert_eq!(t.flights.len(),2);assert!(!t.flights[0].interpolated);assert_eq!(t.flights[1].kind,Some(1));assert_eq!(t.flights[1].position,[1100.0,0.0]);assert!((t.flights[1].age-1.5/60.0).abs()<1e-9);}}
